//! Frozen envelopes/provider facts plus synthetic atomic artifact and authority checks.
use localbrain_core::backend::{
    atlassian::{
        access,
        sync::{self, ExternalExecutionError, ExternalReadExecutor},
    },
    db, Config, Result,
};
use rusqlite::{params_from_iter, types::Value as SqlValue, Connection};
use serde_json::{json, Value};
use std::{fs, sync::Mutex};
fn database() -> Connection {
    let db = Connection::open_in_memory().unwrap();
    db.execute_batch("PRAGMA foreign_keys=ON").unwrap();
    db.execute_batch(db::SCHEMA).unwrap();
    db
}
fn restore(db: &Connection, table: &str, rows: &Value) {
    for row in rows.as_array().unwrap() {
        let row = row.as_object().unwrap();
        let columns = row.keys().map(String::as_str).collect::<Vec<_>>();
        let sql = format!(
            "INSERT INTO {table}({}) VALUES ({})",
            columns.join(","),
            vec!["?"; columns.len()].join(",")
        );
        let values = columns
            .iter()
            .map(|key| match &row[*key] {
                Value::Null => SqlValue::Null,
                Value::String(value) => SqlValue::Text(value.clone()),
                Value::Number(value) => SqlValue::Integer(value.as_i64().unwrap()),
                other => panic!("unexpected fixture scalar {other}"),
            })
            .collect::<Vec<_>>();
        db.execute(&sql, params_from_iter(values)).unwrap();
    }
}
fn assert_result(actual: Result<Value>, case: &Value) {
    if let Some(expected) = case.get("error") {
        let error = actual.unwrap_err();
        assert_eq!(
            json!({"code":error.code,"message":error.message}),
            *expected,
            "{}",
            case["case"]
        );
    } else {
        assert_eq!(
            actual.unwrap_or_else(|e| panic!("{}: {e}", case["case"])),
            case["expected"],
            "{}",
            case["case"]
        );
    }
}
#[test]
fn manifests_dispatches_provider_hashes_and_model_authority_match_frozen_outputs() {
    let manifests: Vec<Value> = serde_json::from_str(MANIFESTS).unwrap();
    assert_eq!(manifests.len(), 22);
    for case in manifests {
        let db = database();
        restore(&db, "external_source_instances", &case["sources"]);
        restore(&db, "external_source_capabilities", &case["capabilities"]);
        let mut config = Config::for_data_dir("/synthetic-not-used");
        config.mcp_call_budget = case["default_call_budget"].as_u64().unwrap().into();
        let result = sync::build_external_sync_manifest(&db, &config, &case["values"]).map(
            |(mut manifest, dispatches)| {
                assert!(localbrain_core::backend::clock::parse_timestamp(
                    manifest["generated_at"].as_str().unwrap()
                )
                .is_some());
                manifest["generated_at"] = json!("__generated_at__");
                json!({"manifest":manifest,"dispatches":dispatches})
            },
        );
        assert_result(result, &case);
    }
    let providers: Vec<Value> = serde_json::from_str(PROVIDERS).unwrap();
    assert_eq!(providers.len(), 13);
    for case in providers {
        assert_result(
            sync::validate_provider_result(
                &case["value"],
                &case["values"]["request"],
                &case["values"]["coverage"],
                &case["values"]["field_allowlist"],
            ),
            &case,
        );
    }
    let models: Vec<Value> = serde_json::from_str(MODELS).unwrap();
    assert_eq!(models.len(), 7);
    for case in models {
        assert_result(
            sync::validate_model_result(&case["value"], case["run_id"].as_str().unwrap()),
            &case,
        );
    }
}
fn source(db: &Connection) -> i64 {
    let source=access::register_source_instance(db,&json!({"instance_key":"synthetic-jira","provider_kind":"mcp_gateway","service":"jira","display_name":"Synthetic"})).unwrap();
    let id = source["id"].as_i64().unwrap();
    access::record_capability_observation(db,id,&json!({"availability":"available","operations":["jira.search_metadata","jira.read_description"],"schema_fingerprint":"a".repeat(64)})).unwrap();
    id
}
fn request(source: i64) -> Value {
    json!({"runner":"claude","source_instance_id":source,"source_kind":"atlassian","scope_kind":"item","call_budget":2,"targets":[{"target_id":"target-1","locator":{"kind":"url","value":"https://jira.example.test/browse/SYN-7"},"coverage":["metadata"],"field_allowlist":["key","summary"],"requests":[{"request_id":"request-1","logical_operation":"jira.search_metadata","arguments":{"jql":"key = SYN-7","fields":["key","summary"]}}]}]})
}
#[test]
fn manifest_locator_admission_preserves_opaque_http_authority_without_resource_registration() {
    let db = database();
    let source = source(&db);
    let config = Config::for_data_dir("/synthetic-not-used");
    let opaque_authority = ["https://user:password", "@", "example.test:opaque/path"].concat();
    for locator in [
        opaque_authority.as_str(),
        "http://:opaque/path",
        "HTTP://example.test/path?x=1#part",
    ] {
        let mut values = request(source);
        values["run_id"] = json!("lb-0123456789ab");
        values["targets"][0]["locator"]["value"] = json!(locator);
        let (manifest, _) = sync::build_external_sync_manifest(&db, &config, &values).unwrap();
        assert_eq!(manifest["targets"][0]["locator"]["value"], locator);
    }
    for locator in [
        "https:///path",
        "ftp://example.test/file",
        "//example.test/path",
    ] {
        let mut values = request(source);
        values["run_id"] = json!("lb-0123456789ab");
        values["targets"][0]["locator"]["value"] = json!(locator);
        assert_eq!(
            sync::build_external_sync_manifest(&db, &config, &values)
                .unwrap_err()
                .code,
            "invalid-manifest"
        );
    }
    assert_eq!(
        db.query_row::<i64, _, _>("SELECT count(*) FROM external_resources", [], |r| r.get(0))
            .unwrap(),
        0
    );
}
#[test]
fn preparation_rolls_back_invalid_parent_and_load_refuses_tampered_envelope_artifact_or_capability()
{
    let temp = tempfile::Builder::new()
        .prefix("lb-atlassian-runs-")
        .tempdir()
        .unwrap();
    let config = Config::for_data_dir(temp.path().join("data"));
    let db = database();
    let id = source(&db);
    let run_root = temp.path().join("runs");
    let mut values = request(id);
    values["workstream_id"] = json!(98765);
    assert!(sync::prepare_external_sync_run(&db, &config, &values, Some(&run_root)).is_err());
    assert_eq!(fs::read_dir(&run_root).unwrap().count(), 0);
    assert_eq!(
        db.query_row::<i64, _, _>("SELECT count(*) FROM maintenance_runs", [], |r| r.get(0))
            .unwrap(),
        0
    );
    values.as_object_mut().unwrap().remove("workstream_id");
    let run = sync::prepare_external_sync_run(&db, &config, &values, Some(&run_root)).unwrap();
    let row = db::row(&db, "SELECT * FROM maintenance_runs WHERE id=?", [&run])
        .unwrap()
        .unwrap();
    let (manifest, _) = sync::load_external_sync_manifest(&db, &config, &row).unwrap();
    assert_eq!(manifest["run_id"], run);
    assert_eq!(row["status"], "queued");
    assert!(run_root.join(&run).join("empty-mcp.json").is_file());
    db.execute(
        "UPDATE external_sync_runs SET selected_target_count=2 WHERE maintenance_run_id=?",
        [&run],
    )
    .unwrap();
    assert_eq!(
        sync::load_external_sync_manifest(&db, &config, &row)
            .unwrap_err()
            .code,
        "external-sync-envelope-mismatch"
    );
    db.execute(
        "UPDATE external_sync_runs SET selected_target_count=1 WHERE maintenance_run_id=?",
        [&run],
    )
    .unwrap();
    let artifact = row["manifest_path"].as_str().unwrap();
    let original = fs::read_to_string(artifact).unwrap();
    let mut forged: Value = serde_json::from_str(&original).unwrap();
    forged["call_budget"] = json!(1);
    fs::write(artifact, forged.to_string()).unwrap();
    assert_eq!(
        sync::load_external_sync_manifest(&db, &config, &row)
            .unwrap_err()
            .code,
        "external-sync-manifest-mismatch"
    );
    fs::write(artifact, original).unwrap();
    access::set_source_instance_enabled(&db, id, false).unwrap();
    assert_eq!(
        sync::load_external_sync_manifest(&db, &config, &row)
            .unwrap_err()
            .code,
        "capability-not-current"
    );
}
struct SyntheticExecutor {
    calls: Mutex<Vec<String>>,
    failure: bool,
}
impl ExternalReadExecutor for SyntheticExecutor {
    fn execute(
        &self,
        dispatch: &access::ToolDispatch,
    ) -> std::result::Result<Value, ExternalExecutionError> {
        self.calls
            .lock()
            .unwrap()
            .push(dispatch.logical_operation.clone());
        if self.failure {
            return Err(ExternalExecutionError::Failed);
        }
        Ok(
            json!({"outcome":"changed","identity":{"remote_id":"77"},"metadata":{"key":"SYN-7","summary":"Host-owned fact"}}),
        )
    }
}
#[test]
fn injected_reads_own_facts_and_model_summary_cannot_add_targets_or_override_them() {
    let db = database();
    let id = source(&db);
    let config = Config::for_data_dir("/synthetic-not-used");
    let mut values = request(id);
    values["run_id"] = json!("lb-synthetic");
    let (manifest, dispatches) = sync::build_external_sync_manifest(&db, &config, &values).unwrap();
    let executor = SyntheticExecutor {
        calls: Mutex::new(vec![]),
        failure: false,
    };
    let mut progress = vec![];
    let mut on_call = |calls: &[Value]| {
        progress.push(json!(calls));
        Ok(())
    };
    let (targets, log) =
        sync::collect_external_sync_evidence(&manifest, &dispatches, &executor, Some(&mut on_call))
            .unwrap();
    assert_eq!(progress.len(), 2);
    assert_eq!(progress[0][0]["outcome"], "running");
    assert_eq!(progress[1][0]["outcome"], "changed");
    assert_eq!(log[0]["tool_name"], "mcp_gateway.gateway_dispatch");
    assert_eq!(
        executor.calls.lock().unwrap().as_slice(),
        ["jira.search_metadata"]
    );
    let summary = json!({"schema":sync::MODEL_RESULT_SCHEMA_VERSION,"run_id":"lb-synthetic","summary":"  Local summary  "});
    let result = sync::assemble_external_sync_result(&manifest, &targets, &summary).unwrap();
    assert_eq!(result["status"], "completed");
    assert_eq!(result["summary"], "Local summary");
    assert_eq!(
        result["targets"][0]["requests"][0]["metadata"]["summary"],
        "Host-owned fact"
    );
    let mut forged = summary.clone();
    forged["targets"] = json!([]);
    assert_eq!(
        sync::assemble_external_sync_result(&manifest, &targets, &forged)
            .unwrap_err()
            .code,
        "invalid-model-result"
    );
    let failing = SyntheticExecutor {
        calls: Mutex::new(vec![]),
        failure: true,
    };
    assert_eq!(
        sync::collect_external_sync_evidence(&manifest, &dispatches, &failing, None)
            .unwrap_err()
            .code,
        "provider-execution-failed"
    );
}
